ALTER TABLE "receipt_confirmations" ADD COLUMN "prohibited_screen" jsonb;--> statement-breakpoint
ALTER TABLE "receipt_confirmations" ADD CONSTRAINT "receipt_prohibited_screen_shape" CHECK ("receipt_confirmations"."prohibited_screen" is null or (case when jsonb_typeof("receipt_confirmations"."prohibited_screen") = 'object' and jsonb_typeof("receipt_confirmations"."prohibited_screen"->'version') = 'string' and jsonb_typeof("receipt_confirmations"."prohibited_screen"->'matches') = 'array' and jsonb_typeof("receipt_confirmations"."prohibited_screen"->'unresolved') = 'array' and jsonb_typeof("receipt_confirmations"."prohibited_screen"->'acknowledged') = 'boolean' then ("receipt_confirmations"."prohibited_screen"->'acknowledged' = 'true'::jsonb) = (jsonb_array_length("receipt_confirmations"."prohibited_screen"->'unresolved') > 0) else false end));